/**
 * A card's rail rows and verdict through the compiled core, records as JavaScript objects (jvm/web/README.md, "Records
 * across the boundary"): the website's `NodeRailsInput` goes in as it is, `ViewExports.viewRailsJs` reads it field by
 * field and builds the `NodeRailsView` object (Java `ViewJs`, generated by tools/web-core/gen-wire.mjs). The object
 * equals `JSON.parse` of the JSON the shared cases keep (conformance/view/rails), key order included.
 */
import type { CoreExports } from "./exports.generated";
import type { NodeRailsInput, NodeRailsView } from "./records.generated";

export function railsThroughCore(
  view: CoreExports["ViewExports"],
  input: NodeRailsInput,
): NodeRailsView {
  return view.viewRailsJs(input) as NodeRailsView;
}
